--- a/serving/kv/cache/evictor.rs
+++ b/serving/kv/cache/evictor.rs
@@ -120,6 +120,22 @@ impl Evictor {
     fn schedule(&self, candidate: EvictCandidate) {
-        self.queue.push(candidate);
+        // latency-aware placement: prefer background queue if touched recently
+        if candidate.touched_within(self.config.latency_grace_ms) {
+            self.background_queue.push(candidate);
+        } else {
+            self.latency_queue.push(candidate.with_score(self.score(&candidate)));
+        }
     }
+
+    fn score(&self, c: &EvictCandidate) -> f64 {
+        // combine age, size and fragmentation penalty into a single priority
+        (c.age_ms as f64 * self.config.age_weight) + (c.size_bytes as f64 * self.config.size_weight) + (c.fragmentation as f64 * self.config.frag_penalty)
+    }
